import { Meta, StoryObj } from "@storybook/react";
import { LoadingBlock } from "./loading-block";

const meta = {
  title: "Primitives/Loading Block",
  component: LoadingBlock,
  parameters: {
    docs: {
      description: {
        component:
          "Animated infinity-loop spinner in the theme's loading color, shown while a block waits for data. " +
          "The SVG scales to its wrapper, so the consumer sets the width through " +
          "`className`; the story adds a demo width for the same reason. The loop is an SMIL animate element, " +
          "which the Default story pauses so Chromatic captures the same frame every time.",
      },
    },
  },
  argTypes: {
    className: { table: { disable: true } },
  },
  render: (args) => (
    <div style={{ width: "6rem" }}>
      <LoadingBlock {...args} />
    </div>
  ),
} satisfies Meta<typeof LoadingBlock>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    // The stroke is animated with SMIL (<animate>), which is not a CSS animation, so freeze it at its first
    // frame to make the snapshot deterministic.
    const svg = canvasElement.querySelector("svg");
    svg?.pauseAnimations();
    svg?.setCurrentTime(0);
  },
};
